   const addTrack=(buffer,gainValue)=>{const source=offline.createBufferSource(),gain=offline.createGain();source.buffer=buffer;gain.gain.value=gainValue;source.connect(gain);gain.connect(offline.destination);source.start(0)};
   addTrack(vocal,Math.max(0,Math.min(120,Number(mixVocalLevel)||0))/100);addTrack(music,Math.max(0,Math.min(120,Number(mixMusicLevel)||0))/100);
